-- SpellSchools.lua : données ZigiAuras + wago.tools DBC
-- Auteur original ZigiAuras : Zigi  https://github.com/ZagiXD/ZigiAuras
--
-- Format compact : enregistrements de largeur fixe triés par spellId (4 caractères base 64), suivis
-- de l'index de la valeur dans sa palette ; recherche dichotomique. ~0,6 Mo résidents au lieu de
-- ~6 Mo de tables. Lecture inchangée : ns.SpellGradients[spellId], ns.SpellSchools[spellId].
-- Pour réencoder : identifiant et index en base 64 (ALPHABET), enregistrements triés par spellId.
local addonName, ns = ...

local ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz+/"
local DIGIT = {}
for i = 1, #ALPHABET do DIGIT[ALPHABET:byte(i)] = i - 1 end

local byte, floor = string.byte, math.floor

local function Decode(data, p, len)
  local v = 0
  for i = p, p + len - 1 do v = v * 64 + DIGIT[byte(data, i)] end
  return v
end

-- data : enregistrements de (4 + idxLen) caractères ; palette[index + 1] = valeur
local function MakeLookup(data, idxLen, palette)
  local recLen = 4 + idxLen
  local count = #data / recLen
  local cache = {} -- spellId -> valeur | false, borné par les sorts réellement lancés
  return setmetatable({}, {
    __index = function(_, id)
      if type(id) ~= "number" or (issecretvalue and issecretvalue(id)) then return nil end
      local c = cache[id]
      if c ~= nil then return c or nil end
      local res = false
      local lo, hi = 0, count - 1
      while lo <= hi do
        local mid = floor((lo + hi) / 2)
        local p = mid * recLen + 1
        local v = Decode(data, p, 4)
        if v == id then
          res = palette[Decode(data, p + 4, idxLen) + 1]
          break
        elseif v < id then lo = mid + 1 else hi = mid - 1 end
      end
      cache[id] = res
      return res or nil
    end,
  })
end

